const $=q=>document.querySelector(q), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='hisui-visual-draft-v1';let state=Game.initial(),saveAvailable=true,view='cover',tab='investigate',selection={a:0,b:11,topic:'alibi',approach:'listen',proof:''},answer=Array(6).fill(''),proofs=Array(3).fill(''),shown=null,openingPage=0;
try{const raw=localStorage.getItem(SAVE);if(raw){state=Game.hydrate(JSON.parse(raw));if(state.result){answer=state.result.answer;proofs=state.result.proofs;}}}catch{saveAvailable=false;}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));}catch{saveAvailable=false;toast('このブラウザでは自動保存できません。保存ファイルを出力してください。');}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
function modal(html){$('#modal').removeAttribute('aria-labelledby');$('#modal-body').innerHTML=html;$('#modal').showModal();}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').onclick=e=>{if(e.target===$('#modal'))$('#modal').close();};
const guide=`<span class="eyebrow">FIELD GUIDE</span><h2>対話でほどく、甘い謎。</h2><ol><li>毎ターン、16人から<strong>聞き手</strong>を1人、残り15人から<strong>話し相手</strong>を選びます。聞き手は毎回変更できます。</li><li>話題に応じた具体的なセリフを選び、必要なら手帳の証拠を提示。<strong>「話しかける」を押すと1ターン</strong>進みます。閲覧・メモ・最終推理はターンを使いません。</li><li>相手の話し方や反応から、伝わる尋ね方を探しましょう。相性が良い相手は信頼を早く得られます。すれ違いやすい相手にも、尋ね方や関連証拠で伝えられます。</li><li>強く追及したり、無関係な証拠を出すと信頼が下がり、未確認の噂を得ることがあります。信頼が下がっても、伝わる尋ね方で回復できます。証拠は失われません。</li><li>5ターンごとに章が進み、新しい照合が可能になります。手がかりは手帳に共有されます。情報が出なければ、必要なときだけ「ヒントを見る」を押せます。手帳で2件の証拠を照合すると、裏付けの揃った重要キーワードを獲得できます。照合はターンを使いません。</li><li>最大30回の聴取後、入手したキーワードで<strong>実行者・道具・方法・原因・目的・場所</strong>を文章にし、3つの証拠で裏付けます。早期提出もできますが、提出後の捜査には戻れません。</li></ol><p class="muted">ホラーや殺人は登場しません。人物の性格は創作上の表現です。会話の相性は、尋ね方や証拠によって補えます。現実の人間関係を判定するものではありません。</p><p class="thin">進行はこのブラウザに自動保存されます。共有端末では「最初から」で消去できます。保存ファイルの出力・読み込みも可能です。</p>`;
$('#help').onclick=()=>modal(guide);$('.brand').onclick=e=>{e.preventDefault();view='cover';render();};
const manor=`<svg viewBox="0 0 440 340" role="img" aria-label="嵐の夜、灯りがともる翡翠荘のイラスト"><defs><pattern id="rain" width="26" height="36" patternUnits="userSpaceOnUse"><path d="M19 0L10 18" stroke="#aebfb2" stroke-width=".7"/></pattern></defs><rect width="440" height="340" fill="url(#rain)"/><circle cx="343" cy="59" r="23" fill="#f1f0df"/><path d="M0 280Q80 230 160 273T440 269V340H0" fill="#bacaba"/><path d="M27 285L53 175 77 285M353 288L384 126 414 288" fill="#627d67"/><path d="M54 212L40 241H72M381 169L362 216H404" fill="none" stroke="#dde5d7"/><path d="M106 154H326V278H106Z" fill="#8caa94" stroke="#284b3c"/><path d="M86 156L214 65 345 156Z" fill="#294e3d"/><path d="M183 125L218 96 251 125V278H183Z" fill="#b9cbb8" stroke="#284b3c"/><path d="M177 126L218 88 259 126" fill="none" stroke="#183f32" stroke-width="9"/><path d="M291 110V57H312V126" fill="#284b3c"/><path d="M205 278V228Q218 209 232 228V278" fill="#244b38"/><g fill="#f0d79d" stroke="#345b43" stroke-width="4"><path d="M125 181H155V212H125Z M278 181H308V212H278Z M125 236H155V264H125Z M278 236H308V264H278Z M205 148H231V185H205Z"/></g><g stroke="#345b43" stroke-width="2"><path d="M140 181V212M125 197H155M293 181V212M278 197H308M218 148V185M205 168H231"/></g><path d="M205 279L173 319H264L232 279" fill="#e5e7d6"/><path d="M93 278H340" stroke="#284b3c" stroke-width="5"/><path d="M81 298H155M284 298H360" stroke="#7a987d"/></svg>`;
function render(){const p=$('#progress');p.textContent=state.started?`残り ${30-state.turn} / 30 対話`:'';if(view==='cover')cover();else if(view==='opening')intro();else if(view==='reading')conversation();else if(view==='result')result();else board();}
function cover(){$('#app').innerHTML=`<section class="hero"><div><span class="eyebrow">A MYSTERY IN SIXTEEN PERSPECTIVES</span><h1>翡翠荘の<br>甘き密室</h1><p class="lead">十六の性格と、消えた至宝。<br>真実は、誰の言葉の間にある？</p><p class="intro-copy">嵐の山荘で、鍵のかかったケースからタルトが消えた。16人の視点を切り替え、証言と証拠をつなぐ。あなたに残された聴取は30回。</p><div class="button-row">${state.started?'<button class="primary" id="resume">捜査を再開する →</button><button id="new-game">最初から</button>':'<button class="primary" id="new-game">物語をはじめる →</button>'}</div><p class="thin muted" style="margin-top:14px">ホラーなし · 途中保存あり · じっくり考える推理ゲーム</p></div><div class="scene">${manor}<span class="stamp">甘い夜には、秘密がある。</span></div></section><div class="facts"><div><strong>16</strong><span>切り替えられる視点</span></div><div><strong>30</strong><span>選び取る対話</span></div><div><strong>06</strong><span>真相へ続く章</span></div></div><p class="footer-note">観察を信じる。推測を疑う。違う視点を、ひとつの答えへ。</p>`;
$('#new-game').onclick=()=>{if(state.started){modal('<h2>新しい捜査を始めますか？</h2><p>このブラウザの進行が置き換わります。残しておきたい場合は、先に捜査画面から保存ファイルを出力してください。</p><button class="primary" id="confirm-new">最初から始める</button>');$('#confirm-new').onclick=()=>{$('#modal').close();start();};}else start();};if($('#resume'))$('#resume').onclick=()=>{view=state.ended?'result':'board';render();};}
function start(){state=Game.initial();state.started=true;answer=Array(6).fill('');proofs=Array(3).fill('');openingPage=0;view='opening';save();render();window.scrollTo(0,0);}
function intro(){$('#app').innerHTML=`<section class="reading"><span class="eyebrow">PROLOGUE / ${openingPage+1} OF ${HISUI.opening.length}</span><h2>嵐の夜と、消えた至宝</h2><p>${HISUI.opening[openingPage]}</p><div class="act-nav"><button id="intro-back" ${openingPage===0?'disabled':''}>← 前へ</button><button class="primary" id="intro-next">${openingPage===HISUI.opening.length-1?'捜査をはじめる →':'続きへ →'}</button></div></section>`;$('#intro-back').onclick=()=>{openingPage--;intro();};$('#intro-next').onclick=()=>{if(openingPage===HISUI.opening.length-1){view='board';tab='investigate';}else openingPage++;render();};}
const nav=[['investigate','対話する'],['notebook','捜査手帳'],['people','人物資料'],['history','会話履歴'],['final','最終推理']];
function board(){const ch=Game.chapter(state);$('#app').innerHTML=`<div class="wrap"><div class="chapter"><div><span class="eyebrow">CHAPTER ${String(ch+1).padStart(2,'0')}</span><h2>${HISUI.acts[ch][0]}</h2></div><div><span class="thin muted">聴取 ${state.turn} / 30</span><div class="bar"><i style="width:${state.turn/30*100}%"></i></div></div></div><nav class="tabs" aria-label="捜査画面">${nav.map(n=>`<button data-tab="${n[0]}" class="${tab===n[0]?'active':''}">${n[1]}</button>`).join('')}</nav><div id="panel"></div><div class="divider"></div><div class="button-row"><button class="quiet" id="export">保存ファイルを出力</button><button class="quiet" id="import">保存ファイルを読み込む</button><span class="thin muted">${saveAvailable?'自動保存されています':'自動保存できないため、保存ファイルをご利用ください'}</span></div><input id="file" type="file" accept="application/json,.json" hidden></div>`;document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;board();});$('#export').onclick=exportSave;$('#import').onclick=()=>$('#file').click();$('#file').onchange=importSave;if(tab==='investigate')investigate();if(tab==='notebook')notebook();if(tab==='people')profiles();if(tab==='history')history();if(tab==='final')finalPanel();}
function personButton(p,which){const excluded=which==='b'&&p.id===selection.a;return '<button class="person '+(selection[which]===p.id?'selected ':'')+(excluded?'excluded':'')+'" data-'+which+'="'+p.id+'" '+(excluded?'disabled':'')+'>'+portrait(p.id,0,'card-portrait')+'<strong>'+p.name+'</strong></button>';}
function personPickerButton(p,which){return `<button class="picker-button" data-picker="${which}" aria-haspopup="dialog">${portrait(p.id,0,'picker-portrait')}<span><strong>${p.name}</strong><small>${which==='a'?'操作する人物を変更':'会話する人物を変更'} ▾</small></span></button>`;}
function openPersonPicker(which){
modal(`<h2 id="picker-title">${which==='a'?'操作するキャラクター':'会話するキャラクター'}</h2><p class="muted">${which==='a'?'聞き手となる人物を選んでください。':'操作する人物以外の15人から選んでください。'}</p><div class="people picker-grid">${HISUI.people.map(p=>personButton(p,which)).join('')}</div>`);
$('#modal').setAttribute('aria-labelledby','picker-title');
document.querySelectorAll(`[data-${which}]`).forEach(el=>el.onclick=()=>{selection[which]=Number(el.dataset[which]);if(selection.a===selection.b)selection.b=(selection.a+1)%16;$('#modal').close();investigate();document.querySelector(`[data-picker="${which}"]`).focus();});
}
function investigate(){if(state.turn>=30){$('#panel').innerHTML=`<div class="notice"><h3>30回の聴取が終了しました。</h3><p>新しい聴取はできません。手帳と履歴を見直し、集めたキーワードで最終推理を完成させてください。</p><button class="primary" id="to-final">最終推理へ →</button></div>`;$('#to-final').onclick=()=>{tab='final';board();};return;}
const a=HISUI.people[selection.a],b=HISUI.people[selection.b],rel=Game.knownRelation(state,a.id,b.id);$('#panel').innerHTML=`${state.turn%5===0?`<div class="notice"><p>${HISUI.acts[Game.chapter(state)][1]}</p></div>`:''}<div class="layout"><section><div class="step-label">01 / 聞き手を選ぶ — あなたの視点</div>${personPickerButton(a,'a')}<div class="step-label">02 / 話し相手を選ぶ — 残りの15人</div>${personPickerButton(b,'b')}<div class="step-label">03 / 話題を選ぶ</div><div class="topic-options">${HISUI.topics.map(t=>`<button data-topic="${t[0]}" class="${selection.topic===t[0]?'selected':''}">${t[1]}<small>${t[2]}</small></button>`).join('')}</div></section><aside class="selection-box"><span class="eyebrow">THIS CONVERSATION</span><div class="pair">${a.name} <span class="muted">→</span> ${b.name}</div><span class="badge ${rel==='bad'?'bad':''}">${{good:'補い合う組み合わせ',bad:'すれ違いやすい組み合わせ',neutral:'尋ね方が鍵になる組み合わせ',null:'この二人の相性はまだ未確認'}[rel]}</span><p class="status-note">${b.name}の信頼：${'●'.repeat(state.trust[b.id])}${'○'.repeat(4-state.trust[b.id])}</p><label class="field">04 / どう尋ねる？</label><div class="options">${Game.dialogueChoices(selection.topic).map(v=>`<button data-approach="${v[0]}" class="${selection.approach===v[0]?'selected':''}">${esc(v[1])}</button>`).join('')}</div><label class="field" for="proof">05 / 提示する証拠（任意）</label><select id="proof"><option value="">証拠を提示しない</option>${state.evidence.map(e=>`<option value="${e}" ${selection.proof===e?'selected':''}>${HISUI.E[e][0]}</option>`).join('')}</select><p class="status-note">尋ね方と証拠が合えば、相性のすれ違いを補えます。強い追及や無関係な証拠は逆効果です。</p><button id="show-hint" class="quiet">ヒントを見る</button><p id="optional-hint" class="status-note" hidden></p><button class="primary full-width" id="talk">話しかける <span class="thin">/ 1ターン</span> →</button></aside></div>`;
document.querySelectorAll('[data-picker]').forEach(el=>el.onclick=()=>openPersonPicker(el.dataset.picker));document.querySelectorAll('[data-a]').forEach(el=>el.onclick=()=>{selection.a=Number(el.dataset.a);if(selection.a===selection.b)selection.b=(selection.a+1)%16;investigate();});document.querySelectorAll('[data-b]').forEach(el=>el.onclick=()=>{selection.b=Number(el.dataset.b);investigate();});document.querySelectorAll('[data-topic]').forEach(el=>el.onclick=()=>{selection.topic=el.dataset.topic;investigate();});document.querySelectorAll('[data-approach]').forEach(el=>el.onclick=()=>{selection.approach=el.dataset.approach;investigate();});$('#show-hint').onclick=()=>{const el=$('#optional-hint');el.hidden=!el.hidden;el.textContent=Game.hint(state,b.id,selection.topic);};$('#proof').onchange=e=>selection.proof=e.target.value;$('#talk').onclick=()=>{try{shown=Game.talk(state,selection);save();view='reading';render();window.scrollTo(0,0);}catch(e){toast(e.message);}};}
function conversation(){const e=shown;$('#app').innerHTML=`<section class="wrap transcript"><span class="eyebrow">CONVERSATION ${String(e.turn).padStart(2,'0')}</span><h2>${HISUI.people[e.a].name}と${HISUI.people[e.b].name}</h2><span class="badge">${HISUI.topics.find(t=>t[0]===e.topic)[1]}</span>${e.lines.map(l=>`<div class="utterance ${l.speaker==='地の文'?'narrator':''}">${l.speaker!=='地の文'?`<span class="speaker">${l.speaker}</span>`:''}<p>${esc(l.text)}</p></div>`).join('')}<div class="receipt"><strong>${e.outcome}</strong>${e.gained.length?`<ul>${e.gained.map(k=>`<li>${HISUI.E[k][0]}を手帳に追加</li>`).join('')}</ul>`:''}${e.keys.length?`<p>キーワード：${e.keys.map(k=>HISUI.K[k][1]).join(' / ')}</p>`:''}</div><div class="button-row"><button class="primary" id="continue">${state.turn>=30?'最終推理へ':'捜査に戻る'} →</button><button id="read-notebook">手帳で照合する</button></div></section>`;$('#continue').onclick=()=>{view='board';if(state.turn>=30)tab='final';render();window.scrollTo(0,0);};$('#read-notebook').onclick=()=>{view='board';tab='notebook';render();window.scrollTo(0,0);};}
function notebook(){$('#panel').innerHTML=`<h3>集めた観察と記録 <span class="thin muted">${state.evidence.length}件</span></h3><p class="muted">証拠は全員で共有。相性によって客観的な事実は変わりません。</p><div class="cards">${state.evidence.map((e,i)=>`<article class="evidence"><small>EVIDENCE ${String(i+1).padStart(2,'0')}</small><h3>${HISUI.E[e][0]}</h3><p>${HISUI.E[e][1]}</p></article>`).join('')||'<p class="empty">まだ証拠はありません。まずはそれぞれが見たことを尋ねてみましょう。</p>'}</div><div class="divider"></div><h3>証拠を照合する</h3><p class="muted">つながると思う記録を2つ選びます。照合はターンを消費せず、失敗しても証拠や信頼は減りません。</p>${state.ended?'<p>結果は確定済みです。照合の記録を読み返せます。</p>':`<div class="final-grid">${[0,1].map(i=>`<label class="field" for="compare-${i}">証拠 ${i+1}<select id="compare-${i}"><option value="">証拠を選ぶ</option>${state.evidence.map(e=>`<option value="${e}">${HISUI.E[e][0]}</option>`).join('')}</select></label>`).join('')}</div><button id="compare-evidence" class="primary">2つの証拠を照合する</button><button id="compare-hint" class="quiet">照合のヒントを見る</button><p id="compare-feedback" role="status"></p><p id="compare-hint-text" hidden></p>`}<div class="divider"></div><h3>照合の記録</h3>${state.comparisons.map(id=>`<article class="list-entry"><p>${esc(Game.comparisons.find(r=>r.id===id).text)}</p></article>`).join('')||'<p class="muted">成立した照合はここに残ります。</p>'}<div class="divider"></div><h3>キーワードの断片</h3><p class="muted">仮説由来のキーワードも含みます。入手できたことと、正しいことは別です。</p><div class="keywords">${state.keys.map(k=>`<span class="keyword"><span class="thin muted">${HISUI.K[k][0]} / </span>${HISUI.K[k][1]}</span>`).join('')}</div><div class="divider"></div><h3>未確認の噂と訂正</h3>${state.rumors.map(r=>`<article class="list-entry"><span class="badge ${r.corrected?'':'pending'}">${r.corrected?'照合により訂正':'未確認'}</span><p>${r.corrected?'<s>':''}${esc(r.text)}${r.corrected?'</s>':''}</p>${r.corrected?`<p>${esc(r.correction)}</p>`:'<p>この噂だけで実行者を決めない。写真・構造・筆記具・夕食の記録から裏付けを探そう。</p>'}</article>`).join('')||'<p class="muted">すれ違いから得た未確認の噂は、ここに記録されます。</p>'}<div class="divider"></div><h3>あなたの推理メモ</h3><label class="thin muted" for="notes">観察・仮説・次に聞きたいこと。閲覧もメモもターンを使いません。</label><textarea id="notes" placeholder="例：鍵を開けた証拠はない。別の取り出し方は？">${esc(state.notes||'')}</textarea>`;if($('#compare-evidence'))$('#compare-evidence').onclick=()=>{try{const r=Game.compare(state,[$('#compare-0').value,$('#compare-1').value]);save();notebook();$('#compare-feedback').textContent=r.text+(r.keys.length?' キーワード：'+r.keys.map(k=>HISUI.K[k][1]).join(' / '):'');}catch(e){$('#compare-feedback').textContent=e.message;}};
if($('#compare-hint'))$('#compare-hint').onclick=()=>{const el=$('#compare-hint-text');el.hidden=!el.hidden;const r=Game.comparisons.find(r=>!state.comparisons.includes(r.id)&&r.min<=state.turn&&r.req.every(e=>Game.has(state,e)));el.textContent=r?'照合の糸口：'+r.pair.map(e=>HISUI.E[e][0]).join(' と '):'今ある記録の不足を、別の人物の証言や次の章の記録で補ってみましょう。';};$('#notes').oninput=e=>{state.notes=e.target.value;save();};}
function profiles(){$('#panel').innerHTML='<p class="muted">表情と言葉から、この人の視点を知る。性格だけで実行者を決めず、記録と照合しましょう。</p><div class="profile-grid">'+HISUI.people.map(p=>'<article class="profile">'+portrait(p.id,0,'profile-portrait')+'<h3>'+p.name+'</h3><p class="quote">「'+p.voice+'」</p><p>'+p.weak+'</p><button data-viewpoint="'+p.id+'">この人を聞き手にする</button></article>').join('')+'</div><div class="divider"></div><h3>館で働く人たち</h3><p class="muted">管理人、庭師、パティシエ。勤務や納品の記録で動きを確かめられます。</p>';document.querySelectorAll('[data-viewpoint]').forEach(b=>b.onclick=()=>{selection.a=Number(b.dataset.viewpoint);if(selection.a===selection.b)selection.b=(selection.a+1)%16;tab='investigate';board();});}
function history(){$('#panel').innerHTML=`<h3>対話の記録</h3>${[...state.history].reverse().map(e=>`<article class="list-entry"><span class="eyebrow">TURN ${String(e.turn).padStart(2,'0')}</span><h3>${HISUI.people[e.a].name} → ${HISUI.people[e.b].name}</h3><p>${HISUI.topics.find(t=>t[0]===e.topic)[1]} · ${e.outcome}</p><button data-history="${e.turn}">会話を読み返す</button></article>`).join('')||'<p class="empty">会話の履歴はここに残ります。</p>'}`;document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{shown=state.history.find(e=>e.turn===Number(b.dataset.history));view='reading';render();window.scrollTo(0,0);});}
function finalPanel(){if(state.ended){view='result';result();return;}$('#panel').innerHTML=`<span class="eyebrow">THE FINAL DEDUCTION</span><h2>断片を、ひとつの説明へ。</h2><p class="muted">入手済みのキーワードだけを使います。仮説も含まれるので、手帳の記録と照合してください。提出前なら何度でも組み替えられます。</p><div class="final-grid">${Game.slots.map((sl,i)=>`<div><label class="field" for="answer-${i}">${String(i+1).padStart(2,'0')} / ${sl[0]}</label><select data-answer="${i}" id="answer-${i}"><option value="">キーワードを選ぶ</option>${state.keys.filter(k=>HISUI.K[k][0]===sl[0]).map(k=>`<option value="${k}" ${answer[i]===k?'selected':''}>${HISUI.K[k][1]}</option>`).join('')}</select></div>`).join('')}</div><div class="sentence" id="sentence">${Game.sentence(answer)}</div><h3>説明を裏付ける証拠</h3><div class="final-grid">${Game.proofSlots.map((sl,i)=>`<div><label class="field" for="final-proof-${i}">${sl[0]}</label><select data-final-proof="${i}" id="final-proof-${i}"><option value="">証拠を選ぶ</option>${state.evidence.map(e=>`<option value="${e}" ${proofs[i]===e?'selected':''}>${HISUI.E[e][0]}</option>`).join('')}</select></div>`).join('')}</div><p class="status-note">${state.turn<30?`まだ${30-state.turn}回の聴取ができます。`:'聴取は終了しています。'} 提出すると、この捜査の結果が確定します。空欄がある状態でも提出できます。</p><button class="primary" id="submit">この推理を提出する →</button>`;document.querySelectorAll('[data-answer]').forEach(el=>el.onchange=()=>{answer[Number(el.dataset.answer)]=el.value;$('#sentence').textContent=Game.sentence(answer);});document.querySelectorAll('[data-final-proof]').forEach(el=>el.onchange=()=>proofs[Number(el.dataset.finalProof)]=el.value);$('#submit').onclick=()=>{modal(`<h2>この説明で、全員に伝えますか？</h2><p>${esc(Game.sentence(answer))}</p><p class="muted">残り${30-state.turn}回。提出後は今回の聴取を続けられません。</p><button class="primary" id="confirm-submit">提出して結末へ</button>`);$('#confirm-submit').onclick=()=>{$('#modal').close();Game.assess(state,answer,proofs);save();view='result';render();window.scrollTo(0,0);};};}
function result(){const r=state.result;$('#app').innerHTML=`<section class="reading"><span class="eyebrow">CASE CLOSED / ${state.turn} CONVERSATIONS</span><h2>${r.rank}</h2><span class="score">${r.score}<span style="font-size:24px"> / 9</span></span><p class="sentence">${esc(Game.sentence(r.answer))}</p><h3>説明の照合</h3>${Game.slots.map((v,i)=>`<p class="thin">${r.correct[i]?'✓':'△'} ${v[0]}：${r.correct[i]?'証拠と整合':'別の説明が必要'} — ${HISUI.K[v[1]][1]}</p>`).join('')}${Game.proofSlots.map((v,i)=>`<p class="thin">${r.evidence[i]?'✓':'△'} ${v[0]}：${HISUI.E[v[1]][0]}</p>`).join('')}<div class="divider"></div><h3>甘き迷宮の真相</h3><p>${Game.solution}</p>${Game.ending.map(p=>`<p>${p}</p>`).join('')}<div class="notice"><p class="thin">${r.rank==='完全解決'?'16の視点が、ひとつの答えにつながりました。':'今回の推理と真相の違いを、手帳で確認できます。次は尋ね方や証拠の組み合わせを変えてみましょう。'}</p></div><div class="button-row"><button class="primary" id="result-home">表紙へ →</button><button id="result-notes">捜査手帳を読む</button></div></section>`;$('#result-home').onclick=()=>{view='cover';render();window.scrollTo(0,0);};$('#result-notes').onclick=()=>{view='board';tab='notebook';render();window.scrollTo(0,0);};}
function exportSave(){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='翡翠荘-捜査記録.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importSave(e){const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error();const s=Game.hydrate(JSON.parse(await f.text()));modal('<h2>保存記録を読み込みますか？</h2><p>現在の進行が読み込んだ記録に置き換わります。</p><button class="primary" id="confirm-import">読み込む</button>');$('#confirm-import').onclick=()=>{state=s;state.started=true;selection.proof='';if(s.result){answer=s.result.answer;proofs=s.result.proofs;}else{answer=Array(6).fill('');proofs=Array(3).fill('');}save();$('#modal').close();view=state.ended?'result':'board';render();toast('保存記録を読み込みました。');};}catch{toast('保存ファイルを確認できませんでした。翡翠荘から出力した記録を選んでください。');}}
